/// <summary>
///     The <c>AVABPTrackingProspectsContract</c> class is the contract class for <c>Tracking prospects</c>
/// </summary>
[DataContractAttribute]
final class AVABPTrackingProspectsContract
{
    str packedQuery;

}

Method.Source:
/// <summary>
///     AVA <c>parmPackedQuery</c> method.
/// </summary>
/// <param name="_packedQuery">
///     <c>str</c> as type
/// </param>
/// <returns>
///     <c>str</c> as return value
/// </returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(AVABPTrackingProspectsQry))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
///     AVA <c>getQuery</c> method.
///     This method unpacks the query and returns it as query object.
/// </summary>
/// <returns>
///     <c>Query</c> as return value
/// </returns>
public Query getQuery()
{
    Query query;

    if (packedQuery)
    {
        query = new Query(SysOperationHelper::base64Decode(packedQuery));
    }
    else
    {
        query = new Query(queryStr(AVABPTrackingProspectsQry));
    }

    return query;
}

/// <summary>
///     AVA <c>setQuery</c> method.
///     This method takes a query object, encodes it and stores the packed query.
/// </summary>
/// <param name="_query">
///     <c>Query</c> as type
/// </param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
///     AVA <c>initQuery</c> method.
/// </summary>
public void initQuery()
{
    // Use this method to add ranges etc. for example:
    Query   newQuery;
    // init Query
    newQuery = new Query(queryStr(AVABPTrackingProspectsQry));
    // add range
    // ...
    // set Query
    this.setQuery(newQuery);
}
